import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ContentManagementTab = () => {
  const [searchBoard, setSearchBoard] = useState(''); // 사찰정보, 리뷰, 사찰댓글, 리뷰댓글
  const [searchKeyword, setSearchKeyword] = useState('');
  const [searchNickname, setSearchNickname] = useState('');
  const [inactivePosts, setInactivePosts] = useState([]);
  const [inactiveComments, setInactiveComments] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const [currentPage, setCurrentPage] = useState(0);
  const [totalPages, setTotalPages] = useState(0);
  const [currentBoardType, setCurrentBoardType] = useState(''); // 현재 조회 중인 게시판 타입

  // 검색창 placeholder 동적 변경
  const getSearchPlaceholder = () => {
    if (searchBoard === '사찰댓글' || searchBoard === '리뷰댓글') {
      return '검색 키워드 (댓글 내용)';
    }
    return '검색 키워드 (제목/내용)';
  };

  // API 요청 함수
  const fetchInactiveContents = async (boardType, keyword = '', nickname = '', page = 0) => {
    setLoading(true);
    setError(null);
    setCurrentBoardType(boardType);

    try {
      const token = localStorage.getItem('accessToken'); // 예시: 로컬 스토리지에서 토큰 가져오기
      if (!token) {
        alert('로그인이 필요합니다.');
        setLoading(false);
        return;
      }

      const params = {
        boardType: boardType, // "TEMPLE", "REVIEW", "TEMPLE_COMMENT", "REVIEW_COMMENT"
        keyword: keyword,
        memberUsername: nickname,
        page: page,
        size: 10, // 한 페이지에 10개씩 (필요에 따라 조절)
        sortBy: 'createdAt',
        sortOrder: 'desc',
      };

      // 백엔드 URL을 명시적으로 지정하거나 package.json에 proxy 설정
      const response = await axios.get('http://localhost:8080/api/admin/contents/inactive', {
        headers: {
          Authorization: `Bearer ${token}`,
        },
        params: params,
      });

      console.log('API 응답:', response.data);

      if (boardType === 'TEMPLE' || boardType === 'REVIEW') {
        setInactivePosts(response.data.temples || response.data.reviews ? (response.data.temples || response.data.reviews).content : []);
        setTotalPages(response.data.temples || response.data.reviews ? (response.data.temples || response.data.reviews).totalPages : 0);
        setInactiveComments([]); // 게시글 조회 시 댓글 목록 초기화
      } else if (boardType === 'TEMPLE_COMMENT' || boardType === 'REVIEW_COMMENT') {
        setInactiveComments(response.data.templeComments || response.data.reviewComments ? (response.data.templeComments || response.data.reviewComments).content : []);
        setTotalPages(response.data.templeComments || response.data.reviewComments ? (response.data.templeComments || response.data.reviewComments).totalPages : 0);
        setInactivePosts([]); // 댓글 조회 시 게시글 목록 초기화
      }

      setCurrentPage(page);

    } catch (err) {
      console.error('비활성화 콘텐츠 조회 실패:', err);
      setError('콘텐츠를 불러오는 데 실패했습니다: ' + (err.response?.data || err.message));
      setInactivePosts([]);
      setInactiveComments([]);
      setTotalPages(0);
    } finally {
      setLoading(false);
    }
  };

  // 컴포넌트 마운트 시 초기 데이터 로드 (예: 기본적으로 리뷰 게시글 목록 로드)
  useEffect(() => {
    fetchInactiveContents('REVIEW'); // 초기 로드 시 '리뷰' 게시글 목록을 가져옴
    setSearchBoard('리뷰'); // 검색 드롭다운 초기값 설정
  }, []);

  const handleSearch = (e) => {
    e.preventDefault();
    let backendBoardType = '';
    if (searchBoard === '사찰정보') {
      backendBoardType = 'TEMPLE';
    } else if (searchBoard === '리뷰') {
      backendBoardType = 'REVIEW';
    } else if (searchBoard === '사찰댓글') {
      backendBoardType = 'TEMPLE_COMMENT';
    } else if (searchBoard === '리뷰댓글') {
      backendBoardType = 'REVIEW_COMMENT';
    } else {
      alert('게시판을 선택해주세요.');
      return;
    }
    fetchInactiveContents(backendBoardType, searchKeyword, searchNickname, 0);
  };

  // 게시글 상세 보기로 이동
  const handleViewPostDetails = (boardType, postId) => {
    // 실제 상세 페이지 URL 패턴에 맞춰 수정 필요
    if (boardType === 'TEMPLE') {
      window.location.href = `/temples/${postId}`; // 예시 URL
    } else if (boardType === 'REVIEW') {
      window.location.href = `/reviews/${postId}`; // 예시 URL
    }
  };

  // 댓글 상세 보기로 이동 (댓글 자체의 상세 페이지가 없다면 부모 게시글로 이동)
  const handleViewCommentDetails = (boardType, commentId, parentId) => {
    // 실제 상세 페이지 URL 패턴에 맞춰 수정 필요
    if (boardType === 'TEMPLE_COMMENT') {
      alert(`사찰 댓글 ${commentId} 상세 보기 (사찰 ID: ${parentId}) - 상세 페이지는 구현 필요`);
      // window.location.href = `/temples/${parentId}#comment-${commentId}`; // 예시: 사찰 상세 페이지의 해당 댓글 위치로 이동
    } else if (boardType === 'REVIEW_COMMENT') {
      alert(`리뷰 댓글 ${commentId} 상세 보기 (리뷰 ID: ${parentId}) - 상세 페이지는 구현 필요`);
      // window.location.href = `/reviews/${parentId}#comment-${commentId}`; // 예시: 리뷰 상세 페이지의 해당 댓글 위치로 이동
    }
  };

  // 게시글 활성화/삭제
  const handlePostAction = async (post, actionType) => {
    const postId = post.reviewId || post.templeId;
    const boardType = post.boardType;
    const contentName = post.title || post.templeName;

    const token = localStorage.getItem('accessToken');
    if (!token) {
      alert('로그인이 필요합니다.');
      return;
    }

    try {
      if (actionType === '활성화') {
        if (!window.confirm(`게시글 "${contentName}"을 활성화하시겠습니까?`)) return;
        if (boardType === 'TEMPLE') {
          await axios.patch(`http://localhost:8080/api/temples/${postId}/status`, null, {
            params: { isActive: true },
            headers: { Authorization: `Bearer ${token}` },
          });
        } else if (boardType === 'REVIEW') {
          await axios.patch(`http://localhost:8080/api/reviews/${postId}/status`, null, {
            params: { isActive: true },
            headers: { Authorization: `Bearer ${token}` },
          });
        }
        alert(`게시글 "${contentName}"을 활성화했습니다.`);
      } else if (actionType === '삭제') {
        if (!window.confirm(`게시글 "${contentName}"을 정말 삭제하시겠습니까? (소프트 삭제)`)) return;
        if (boardType === 'TEMPLE') {
          await axios.delete(`http://localhost:8080/api/temples/${postId}`, { // 사찰은 DELETE가 소프트 삭제 역할
            headers: { Authorization: `Bearer ${token}` },
          });
        } else if (boardType === 'REVIEW') {
          await axios.patch(`http://localhost:8080/api/reviews/${postId}/soft-delete`, null, {
            headers: { Authorization: `Bearer ${token}` },
          });
        }
        alert(`게시글 "${contentName}"을 삭제(비활성화)했습니다.`);
      }
      fetchInactiveContents(currentBoardType, searchKeyword, searchNickname, currentPage);

    } catch (err) {
      console.error(`${actionType} 액션 실패:`, err.response ? err.response.data : err.message);
      alert(`${actionType} 실패: ` + (err.response ? err.response.data.message || err.response.data : err.message));
    }
  };

  // 댓글 활성화/삭제
  const handleCommentAction = async (comment, actionType) => {
    const commentId = comment.reviewCommentId || comment.templeCommentId;
    const boardType = comment.boardType;
    const parentId = comment.reviewId || comment.templeId; // 부모 게시글 ID
    const contentText = comment.content;

    const token = localStorage.getItem('accessToken');
    if (!token) {
      alert('로그인이 필요합니다.');
      return;
    }

    try {
      if (actionType === '활성화') {
        alert(`댓글 "${contentText}" 활성화 기능은 백엔드 API에 직접 구현되어 있지 않습니다. (isDeleted=false API 필요)`);
        // ⭐ 중요: 백엔드에 댓글 활성화 (isDeleted=false) API가 있다면 여기에 호출 로직 추가
        // 예: await axios.patch(`http://localhost:8080/api/${boardType === 'TEMPLE_COMMENT' ? 'temples' : 'reviews'}/${parentId}/comments/${commentId}/status`, { isDeleted: false }, { headers: { Authorization: `Bearer ${token}` } });
      } else if (actionType === '삭제') {
        if (!window.confirm(`댓글 "${contentText}"을 정말 삭제하시겠습니까? (소프트 삭제)`)) return;
        if (boardType === 'TEMPLE_COMMENT') {
          await axios.delete(`http://localhost:8080/api/temples/${parentId}/comments/${commentId}`, {
            headers: { Authorization: `Bearer ${token}` },
          });
        } else if (boardType === 'REVIEW_COMMENT') {
          await axios.delete(`http://localhost:8080/api/reviews/${parentId}/comments/${commentId}`, {
            headers: { Authorization: `Bearer ${token}` },
          });
        }
        alert(`댓글 "${contentText}"을 삭제(비활성화)했습니다.`);
      }
      fetchInactiveContents(currentBoardType, searchKeyword, searchNickname, currentPage);

    } catch (err) {
      console.error(`${actionType} 액션 실패:`, err.response ? err.response.data : err.message);
      alert(`${actionType} 실패: ` + (err.response ? err.response.data.message || err.response.data : err.message));
    }
  };

  // 페이지네이션 렌더링
  const renderPagination = () => {
    const pages = [];
    for (let i = 0; i < totalPages; i++) {
      pages.push(
        <button
          key={i}
          className={`page-button ${i === currentPage ? 'active' : ''}`}
          onClick={() => fetchInactiveContents(currentBoardType, searchKeyword, searchNickname, i)}
          disabled={loading}
        >
          {i + 1}
        </button>
      );
    }
    return <div className="pagination">{pages}</div>;
  };

  return (
    <div className="tab-content-section content-management-tab">
      <h3 className="tab-content-title">콘텐츠 관리 🛡️</h3>
      <form onSubmit={handleSearch} className="search-form">
        <select value={searchBoard} onChange={(e) => setSearchBoard(e.target.value)}>
          <option value="">게시판 선택</option>
          <option value="사찰정보">사찰정보</option>
          <option value="리뷰">리뷰</option>
          <option value="사찰댓글">사찰댓글</option>
          <option value="리뷰댓글">리뷰댓글</option>
        </select>
        <input
          type="text"
          placeholder={getSearchPlaceholder()}
          value={searchKeyword}
          onChange={(e) => setSearchKeyword(e.target.value)}
        />
        <input
          type="text"
          placeholder="작성자 닉네임"
          value={searchNickname}
          onChange={(e) => setSearchNickname(e.target.value)}
        />
        <button type="submit" className="search-button" disabled={loading}>검색</button>
      </form>

      {loading && <p>데이터를 불러오는 중입니다... ⏳</p>}
      {error && <p className="error-message">오류: {error}</p>}

      {/* 게시글 목록 */}
      {['TEMPLE', 'REVIEW'].includes(currentBoardType) && (
        <>
          <h4 style={{ marginBottom: '15px' }}>비활성화 게시글 목록 ({inactivePosts.length}개)</h4>
          <div className="admin-table-container"> {/* ⭐ 이 div에만 새로운 컨테이너 클래스 추가 */}
            <table className="admin-data-table"> {/* ⭐ 이 table에만 새로운 테이블 클래스 추가 */}
              <thead>
                <tr>
                  <th>게시판</th>
                  <th>제목</th>
                  <th>작성자</th>
                  <th>상태</th>
                  <th>관리</th>
                </tr>
              </thead>
              <tbody>
                {inactivePosts.length > 0 ? (
                  inactivePosts.map(post => (
                    <tr key={post.reviewId || post.templeId}>
                      <td>
                        <span className={`board-type-label ${post.boardType === 'TEMPLE' ? 'temple-board' : 'review-board'}`}>
                          {post.boardType === 'TEMPLE' ? '사찰정보' : '리뷰'}
                        </span>
                      </td>
                      <td>
                        <a href="#" onClick={(e) => { e.preventDefault(); handleViewPostDetails(post.boardType, post.reviewId || post.templeId); }}>
                          {post.title || post.templeName}
                        </a>
                      </td>
                      <td>{post.memberUsername || 'N/A'}</td> {/* 사찰은 작성자 N/A */}
                      <td>
                        <span className={post.isDeleted ? 'status-deleted' : (post.isActive ? 'status-active' : 'status-inactive')}>
                          {post.isDeleted ? '삭제됨' : (post.isActive ? '활성' : '비활성')}
                        </span>
                      </td>
                      <td>
                        <div className="action-buttons-group"> {/* 버튼 그룹화 */}
                          <button
                            className="action-button small-action-button"
                            onClick={() => handlePostAction(post, '활성화')}
                            disabled={post.isActive === true || post.isDeleted === false}
                          >
                            활성화
                          </button>
                          <button
                            className="action-button delete-button small-action-button"
                            onClick={() => handlePostAction(post, '삭제')}
                            disabled={post.isDeleted === true}
                          >
                            삭제
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="5" className="no-data-message">비활성화된 게시글이 없어요. ✨</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </>
      )}

      <hr style={{ margin: '40px 0', borderColor: '#eee' }} /> {/* 구분선 추가 */}

      {/* 댓글 목록 */}
      {['TEMPLE_COMMENT', 'REVIEW_COMMENT'].includes(currentBoardType) && (
        <>
          <h4 style={{ marginTop: '40px', marginBottom: '15px' }}>비활성화 댓글 목록 ({inactiveComments.length}개)</h4>
          <div className="admin-table-container"> {/* ⭐ 이 div에만 새로운 컨테이너 클래스 추가 */}
            <table className="admin-data-table"> {/* ⭐ 이 table에만 새로운 테이블 클래스 추가 */}
              <thead>
                <tr>
                  <th>게시판</th>
                  <th>내용</th>
                  <th>작성자</th>
                  <th>상태</th>
                  <th>관리</th>
                </tr>
              </thead>
              <tbody>
                {inactiveComments.length > 0 ? (
                  inactiveComments.map(comment => (
                    <tr key={comment.reviewCommentId || comment.templeCommentId}>
                      <td>
                        <span className={`board-type-label ${comment.boardType === 'TEMPLE' ? 'temple-board' : 'review-board'}`}>
                          {comment.boardType === 'TEMPLE' ? '사찰정보' : '리뷰'}
                        </span>
                      </td>
                      <td>
                        <a href="#" onClick={(e) => { e.preventDefault(); handleViewCommentDetails(comment.boardType, comment.reviewCommentId || comment.templeCommentId, comment.reviewId || comment.templeId); }}>
                          {comment.content}
                        </a>
                      </td>
                      <td>{comment.memberUsername || 'N/A'}</td>
                      <td>
                        <span className={comment.isDeleted ? 'status-deleted' : (comment.isActive ? 'status-active' : 'status-inactive')}>
                          {comment.isDeleted ? '삭제됨' : (comment.isActive ? '활성' : '비활성')}
                        </span>
                      </td>
                      <td>
                        <div className="action-buttons-group"> {/* 버튼 그룹화 */}
                          {/* 댓글 활성화 버튼은 백엔드 API에 따라 주석 해제 가능 */}
                          {/*
                          <button
                            className="action-button small-action-button"
                            onClick={() => handleCommentAction(comment, '활성화')}
                            disabled={comment.isDeleted === false}
                          >
                            활성화
                          </button>
                          */}
                          <button
                            className="action-button delete-button small-action-button"
                            onClick={() => handleCommentAction(comment, '삭제')}
                            disabled={comment.isDeleted === true}
                          >
                            삭제
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="5" className="no-data-message">비활성화된 댓글이 없어요. ✨</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </>
      )}

      {/* 페이지네이션 버튼 */}
      {totalPages > 1 && renderPagination()}
    </div>
  );
};

export default ContentManagementTab;
